use kynex_core::{Core,write_json};use serde_json::json;use std::sync::Arc;
#[tokio::main]async fn main(){
 let t=tempfile::tempdir().unwrap();let c=Core::new(t.path().into(),Arc::new(|_|{})).unwrap();
 let info=c.get("https://api.modrinth.com/v2/project/translations-for-sodium").await.unwrap();let pid=info["id"].as_str().unwrap();
 let list=c.get(&format!("https://api.modrinth.com/v2/project/{pid}/version?include_changelog=false&game_versions=%5B%221.21.1%22%5D")).await.unwrap();
 let row=list.as_array().unwrap().iter().rev().find(|v|v["dependencies"].as_array().is_some_and(|d|d.iter().any(|d|d["dependency_type"]=="required"))).expect("No historical resource pack with required dependency");
 write_json(&c.instance("qa").unwrap().join("kxl.json"),&json!({"id":"qa","name":"QA","version":"1.21.1","loader":"fabric","settings":{"isolation":"all"}})).unwrap();
 let p=json!({"id":"qa","project":pid,"versionId":row["id"],"kind":"resourcepacks","source":"modrinth"});
 let preview=c.dispatch("resource_requirements",p.clone()).await.unwrap();println!("Historical Sodium Translations {}: {}",row["version_number"],preview);assert!(preview["dependencies"].as_array().unwrap().iter().any(|d|d["kind"]=="mods"));
 c.dispatch("install_project",p.clone()).await.unwrap();let root=c.instance("qa").unwrap();let resources=root.join("resourcepacks");let mods=root.join("mods");assert!(std::fs::read_dir(&resources).unwrap().flatten().any(|e|e.path().extension().is_some_and(|x|x=="zip")));assert!(std::fs::read_dir(&mods).unwrap().flatten().any(|e|e.path().extension().is_some_and(|x|x=="jar")));assert!(!std::fs::read_dir(&resources).unwrap().flatten().any(|e|e.path().extension().is_some_and(|x|x=="jar")));let second=c.dispatch("resource_requirements",p).await.unwrap();assert!(second["dependencies"].as_array().unwrap().iter().all(|d|d["installed"]==true));println!("Pack ZIP in resourcepacks, Sodium and required JARs in mods; second check recognizes matching installed files");
 let shaders=c.dispatch("project_versions",json!({"id":"qa","kind":"shaderpacks","source":"modrinth","project":"complementary-unbound","game":"1.21.1","paged":true})).await.unwrap();let selected=shaders["versions"].as_array().unwrap().last().unwrap();let version=c.get(&format!("https://api.modrinth.com/v2/version/{}",selected["id"].as_str().unwrap())).await.unwrap();let hint=c.dispatch("resource_requirements",json!({"id":"qa","kind":"shaderpacks","source":"modrinth","project":version["project_id"],"versionId":selected["id"]})).await.unwrap();assert!(hint["notes"].as_array().unwrap().iter().any(|s|s.as_str().unwrap().contains("Iris")));println!("Historical shader versions and missing shader-loader hint checked");
}
